from collections import Counter

def find_doubles(values):
    cnt = Counter(values)
    parts = []
    for v in sorted(cnt):
        if cnt[v] == 2:
            parts.append(f"{v} {v}")
    return ' '.join(parts)

import java.util.*;

class Solution {
    static String findDoubles(int[] values) {
        Map<Integer, Integer> cnt = new TreeMap<>();
        for (int v : values) cnt.merge(v, 1, Integer::sum);
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, Integer> e : cnt.entrySet())
            if (e.getValue() == 2) {
                if (sb.length() > 0) sb.append(' ');
                sb.append(e.getKey()).append(' ').append(e.getKey());
            }
        return sb.toString();
    }
}

#include <bits/stdc++.h>
using namespace std;

string findDoubles(vector<int>& values) {
    map<int, int> cnt;
    for (int v : values) cnt[v]++;
    string out;
    for (auto& [v, c] : cnt) {
        if (c == 2) {
            if (!out.empty()) out += ' ';
            out += to_string(v) + " " + to_string(v);
        }
    }
    return out;
}
